() => {
  const all = Array.from(document.querySelectorAll('*'));
  const matches = [];
  for (const el of all) {
    const t = (el.textContent || '');
    if (el.children.length === 0 && (t.includes('监测') || t.includes('自动更新'))) {
      matches.push({ tag: el.tagName, text: t.trim().slice(0, 80) });
    }
  }
  // also check aria-labels / titles for refresh-like icons
  const icons = Array.from(document.querySelectorAll('[aria-label],[title]')).filter(el => {
    const s = (el.getAttribute('aria-label') || '') + (el.getAttribute('title') || '');
    return /监测|刷新|refresh|monitor/i.test(s);
  }).map(el => ({ tag: el.tagName, aria: el.getAttribute('aria-label'), title: el.getAttribute('title') }));
  return { matches, icons };
